extra_css:
/* dark: blackboard with chalk dust */
:root.lia-variant-dark .lia-canvas { background-image: url('embed:assets/chalk-noise.svg'); }
:root.lia-variant-dark .lia-slide__content :is(h1, h2, h3, .h1, .h2, .h3) { text-shadow: 0 0 1px rgba(255, 255, 255, 0.55), 0 0 0.8rem rgba(255, 255, 255, 0.18); }
:root.lia-variant-dark .lia-slide__content :is(p, li, td, th) { text-shadow: 0 0 1px rgba(255, 255, 255, 0.28); }
/* wooden frame around the board in presentation / slides mode */
:root.lia-variant-dark .lia-canvas:is(.lia-mode--presentation, .lia-mode--slides) .lia-slide__container { border: 1.2rem solid #6b4a2e; border-radius: 0.6rem; box-shadow: inset 0 0 2.4rem rgba(0, 0, 0, 0.45), 0 0.4rem 1.2rem rgba(0, 0, 0, 0.4); }
/* light: squared school paper with a red margin line */
:root.lia-variant-light .lia-canvas { background-image: linear-gradient(rgba(47, 85, 164, 0.09) 1px, transparent 1px), linear-gradient(90deg, rgba(47, 85, 164, 0.09) 1px, transparent 1px); background-size: 2rem 2rem; }
:root.lia-variant-light .lia-slide__content { border-left: 2px solid rgba(214, 69, 69, 0.55); padding-left: 3rem; }
/* hand-drawn underline under every section title (.h1 = section title at any level) */
.lia-slide__content .h1::after { content: ''; display: block; width: 24rem; max-width: 70%; height: 1.8rem; margin-top: 0.2rem; background: url('embed:assets/chalk-underline.svg') left center / 100% 100% no-repeat; }
:root.lia-variant-light .lia-slide__content .h1::after { background-image: url('embed:assets/ink-underline.svg'); }
/* chalk lines instead of solid rules and tinted boxes */
hr, .lia-divider { height: 0; border: 0; border-top: 2px dashed rgba(var(--color-text), 0.45); }
.lia-quote:not([class*='alert']) { background: transparent; border: 2px dashed rgba(var(--color-text), 0.4); }
.lia-code__input { border-width: 2px; }
